CREATE OR REPLACE FUNCTION public.finance_fx_draft_check(t uuid,q public.finance_entry_drafts) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF q.kind IN('fx_payment','fx_revaluation') THEN RAISE EXCEPTION 'FX approval is not available yet: isolated payment and reversal verification is incomplete. The draft is retained; no posting has occurred.';END IF;END $$;REVOKE ALL ON FUNCTION public.finance_fx_draft_check(uuid,public.finance_entry_drafts) FROM PUBLIC,anon;COMMENT ON FUNCTION public.finance_fx_draft_check(uuid,public.finance_entry_drafts) IS 'Fail-closed verification gate for FX drafts until isolated approval, matching, deposits and reversal checks pass.';